const safe = s => { const str = (s || "").toString(); return /^[+=\-@]/.test(str) ? "'" + str : str; };
const body = $input.first().json.body || $input.first().json;
const id_pedido = (body.id_pedido || "").toString();
const importe = Number(body.importe || 0);
const metodo = body.metodo || "efectivo";
const modo_reparto = body.modo_reparto || "regla_defecto";
const quien_cobro = body.quien_cobro || "Noel";

let bote, reparto, por_socio;
if (modo_reparto === "personalizado") {
  bote = Number(body.bote_personalizado || 0);
  reparto = Number(body.reparto_personalizado || 0);
  por_socio = reparto / 2;
  if (Math.abs(bote + reparto - importe) > 0.01) {
    throw new Error("bote + reparto != importe");
  }
} else {
  por_socio = Math.floor(importe * 2 / 5 / 20) * 20;
  reparto = por_socio * 2;
  bote = importe - reparto;
}

const nota_reparto = safe(body.nota_reparto);
const hoy = new Date().toISOString().slice(0, 10);
const ts = Date.now();

return [{
  json: {
    id_pedido, importe, metodo, modo_reparto, nota_reparto, quien_cobro,
    bote, reparto, por_socio,
    id_cobro: "C" + ts,
    id_reparto_E: "R" + ts + "-E",
    id_reparto_N: "R" + ts + "-N",
    id_reparto_B: "R" + ts + "-B",
    fecha: hoy
  }
}];

const prep = $('Prepare pedidos-entregar').item.json;
const pedidos = $('Sheets read pedidos (for entregar)').all().map(i => i.json).filter(p => p.id_pedido);
const pedido = pedidos.find(p => p.id_pedido === prep.id_pedido);
if (!pedido) throw new Error("pedido no encontrado: " + prep.id_pedido);
if (pedido.estado !== "pendiente") throw new Error("pedido ya " + pedido.estado);
return [{ json: prep }];

const prep = $('Prepare pedidos-entregar').item.json;
const hoy = prep.fecha;
const cobrador = prep.quien_cobro;

function mkRow(id, socio, importe) {
  const autoEntregado = socio === cobrador && importe > 0;
  let estado;
  if (importe === 0) estado = "no_aplica";
  else if (autoEntregado) estado = "entregado";
  else estado = "pendiente_entregar";
  return {
    id_reparto: id,
    id_cobro: prep.id_cobro,
    fecha: hoy,
    socio,
    importe,
    estado,
    fecha_entregado: autoEntregado ? hoy : ""
  };
}

return [
  { json: mkRow(prep.id_reparto_E, "Eric", prep.por_socio) },
  { json: mkRow(prep.id_reparto_N, "Noel", prep.por_socio) },
  { json: mkRow(prep.id_reparto_B, "bote", prep.bote) }
];

