  json: {
    importe, concepto, parte_eric, parte_noel,
    id_mov: "M" + ts,
    id_cobro: "RB" + ts,
    id_reparto_E: "R" + ts + "-E",
    id_reparto_N: "R" + ts + "-N",
    fecha: hoy
  }
}];

